import pytest
import ops
from ops import testing

captured = {}

class MyCharm(ops.CharmBase):
    def __init__(self, framework):
        super().__init__(framework)
        self.framework.observe(self.on.update_status, self._on_update_status)

    def _on_update_status(self, event):
        try:
            relation = self.model.get_relation('db', 1)
            captured['data'] = relation.data[self.app]
        except ops.ModelError as e:
            captured['error'] = e

def test_permission_denied_reads_empty():
    ctx = testing.Context(MyCharm, meta={'name': 'my-charm', 'requires': {'db': {'interface': 'db'}}})
    ctx.run(ctx.on.update_status(), testing.State(relations=[testing.Relation('db', id=1)]))
    assert captured['error'] == ops.RelationNotFoundError('relation not found')
